package br.twbstudio.instalador;
import com.jcraft.jsch.*;import java.io.*;import java.util.concurrent.*;import android.app.*;import android.widget.*;import org.json.*;
final class RootAccess {
 static String exec(Session s,String cmd)throws Exception{ChannelExec c=(ChannelExec)s.openChannel("exec");c.setCommand(cmd);InputStream in=c.getInputStream();c.connect(8000);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];long end=System.currentTimeMillis()+20000;try{while(System.currentTimeMillis()<end){while(in.available()>0){int n=in.read(buffer,0,Math.min(buffer.length,in.available()));if(n<0)break;out.write(buffer,0,n);if(out.size()>2000000)throw new IOException("Resposta muito grande");}if(c.isClosed()){if(c.getExitStatus()!=0)throw new IOException("Comando recusado pela TV");return out.toString("UTF-8");}Thread.sleep(40);}throw new IOException("TV não respondeu a tempo");}finally{c.disconnect();}}
 static Session connect(Main a,String host,String password)throws Exception{return connect(a,host,password,true);}
 static Session connect(Main a,String host,String password,boolean check)throws Exception{
  if(!java.net.InetAddress.getByName(host).isSiteLocalAddress())throw new IOException("Use o IP local da TV");
  JSch j=new JSch();File known=new File(a.getFilesDir(),"lg-root-hosts");if(known.exists())j.setKnownHosts(known.getAbsolutePath());
  String privateKey=LgSetup.read(a,"root-private:"+host);if(!privateKey.isEmpty())j.addIdentity("freedomtv-phone",privateKey.getBytes("UTF-8"),null,null);Session s=j.getSession("root",host,22);s.setPassword(password);s.setConfig("PreferredAuthentications",privateKey.isEmpty()?"password":"publickey");s.setConfig("StrictHostKeyChecking","ask");s.setTimeout(30000);
  s.setUserInfo(new UserInfo(){public String getPassword(){return password;}public String getPassphrase(){return null;}public boolean promptPassword(String m){return true;}public boolean promptPassphrase(String m){return false;}public void showMessage(String m){}public boolean promptYesNo(String m){CompletableFuture<Boolean> f=new CompletableFuture<>();a.runOnUiThread(()->new AlertDialog.Builder(a).setTitle("Autorizar Homebrew em "+host).setMessage(m).setPositiveButton("Autorizar",(d,w)->f.complete(true)).setNegativeButton("Cancelar",(d,w)->f.complete(false)).setOnCancelListener(d->f.complete(false)).show());try{return f.get(90,TimeUnit.SECONDS);}catch(Exception e){return false;}}});
  try{s.connect(12000);if(!check)return s;if(!"0".equals(exec(s,"id -u").trim()))throw new IOException("A conexão não tem root");JSONObject hb=new JSONObject(exec(s,"luna-send -n 1 luna://com.webos.applicationManager/getAppInfo '{\"id\":\"org.webosbrew.hbchannel\"}'"));if(!hb.optBoolean("returnValue"))throw new IOException("Homebrew Channel não confirmado");try(FileOutputStream out=new FileOutputStream(known)){for(HostKey k:j.getHostKeyRepository().getHostKey())out.write((k.getHost()+" "+k.getType()+" "+k.getKey()+"\n").getBytes("UTF-8"));}return s;}catch(Exception e){s.disconnect();throw e;}
 }
 static void configure(Main a){if(a.busy)return;final String host=a.ip==null?a.prefs.getString("host",""):a.ip.getText().toString().trim();if(!host.matches("[0-9.]+")){a.say("Informe o IPv4 da TV");return;}
 if(!LgSetup.read(a,"root-private:"+host).isEmpty()){a.busy=true;a.say("Conectando pelo Homebrew…");new Thread(()->{Session session=null;boolean ok=false;try{session=connect(a,host,"");ok=true;a.prefs.edit().putString("host",host).putBoolean("root:"+host,true).apply();a.runOnUiThread(()->{a.busy=false;a.themes();});new Thread(()->{try{fetchApps(a,host);}catch(Exception ignored){}}).start();}catch(Exception e){android.util.Log.e("FreedomTV","Homebrew com chave salva falhou",e);final String why=String.valueOf(e.getMessage());a.say("O Homebrew não aceitou a conexão ("+why+"). Vamos autorizar este celular de novo.");a.runOnUiThread(()->{a.busy=false;pair(a,host);});}finally{if(session!=null)session.disconnect();if(!ok)a.busy=false;}}).start();return;}
 pair(a,host);}
 static void pair(Main a,String host){
 new AlertDialog.Builder(a).setTitle("Autorizar este celular no Homebrew").setMessage("Na sua LG com root, ative SSH Server e Telnet no Homebrew Channel. Este celular vai criar uma chave própria e adicioná-la à TV, preservando as autorizações existentes. Faça isso na sua rede Wi-Fi de confiança. Depois da confirmação, você pode desligar Telnet e manter SSH Server ativo. Não precisa digitar uma senha.").setPositiveButton("Autorizar celular",(d,w)->{a.busy=true;a.say("Autorizando celular…");new Thread(()->{Session session=null;try{RootPairing.authorize(a,host);session=connect(a,host,"");a.prefs.edit().putString("host",host).putBoolean("root:"+host,true).apply();a.runOnUiThread(()->{a.busy=false;a.cleanupChoice();});new Thread(()->{try{fetchApps(a,host);}catch(Exception ignored){}}).start();}catch(Exception e){android.util.Log.e("FreedomTV","autorizar celular falhou",e);a.prefs.edit().putBoolean("root:"+host,false).apply();a.say("Não conectou pelo Homebrew: "+e.getMessage()+". Na TV, no Homebrew Channel, ligue SSH Server e Telnet e tente de novo.");}finally{if(session!=null)session.disconnect();a.busy=false;}}).start();}).setNegativeButton("Cancelar",null).show();}
 // The TV answers in one go: only the removable apps (same filter as before), each with its 80x80 logo in base64.
 static final String LIST_APPS="node -e 'var fs=require(\"fs\"),cp=require(\"child_process\");var a=JSON.parse(cp.execSync(\"luna-send -n 1 luna://com.webos.applicationManager/listApps {}\")).apps;var o=[];a.forEach(function(x){var id=x.id||\"\";if(!/^[a-zA-Z0-9._-]+$/.test(id)||/^(com\\.webos\\.|com\\.palm|org\\.webosbrew\\.|com\\.twbstudio\\.)/.test(id)||x.systemApp||!x.removable)return;var i=\"\";try{var p=x.folderPath+\"/\"+x.icon;if(fs.statSync(p).size<80000)i=fs.readFileSync(p).toString(\"base64\");}catch(e){}o.push({id:id,title:x.title||id,icon:i});});o.sort(function(p,q){return p.title.localeCompare(q.title);});process.stdout.write(JSON.stringify(o));'";
 static File appsFile(Main a,String host){return new File(a.getFilesDir(),"tv-apps-"+host.replace('.','_')+".json");}
 static JSONArray cachedApps(Main a,String host){try(FileInputStream in=new FileInputStream(appsFile(a,host))){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;while((n=in.read(buf))>0)b.write(buf,0,n);return new JSONArray(b.toString("UTF-8"));}catch(Exception e){return null;}}
 static JSONArray fetchApps(Main a,String host)throws Exception{Session s=null;try{s=connect(a,host,LgSetup.read(a,"root:"+host),false);String raw=exec(s,LIST_APPS).trim();JSONArray list=new JSONArray(raw);try(FileOutputStream out=new FileOutputStream(appsFile(a,host))){out.write(raw.getBytes("UTF-8"));}return list;}finally{if(s!=null)s.disconnect();}}
 static void manage(Main a){if(a.busy)return;String host=a.prefs.getString("host","");if(!a.prefs.getBoolean("root:"+host,false)){a.say("Conecte pelo Homebrew para gerenciar aplicativos nesta versão.");return;}
  JSONArray cached=cachedApps(a,host);
  if(cached!=null){showApps(a,host,cached);new Thread(()->{try{fetchApps(a,host);}catch(Exception ignored){}}).start();return;}   // opens at once; the list is refreshed for next time
  a.busy=true;a.say("Carregando aplicativos da TV…");new Thread(()->{try{JSONArray list=fetchApps(a,host);a.runOnUiThread(()->{a.busy=false;a.say("");showApps(a,host,list);});}catch(Exception e){a.say("Não foi possível listar: "+e.getMessage());}finally{a.busy=false;}}).start();}
 static void showApps(Main a,String host,JSONArray apps){
  if(apps.length()==0){a.say("Nenhum aplicativo removível elegível encontrado.");return;}
  java.util.ArrayList<String> names=new java.util.ArrayList<>(),ids=new java.util.ArrayList<>();java.util.ArrayList<CheckBox> boxes=new java.util.ArrayList<>();
  LinearLayout list=new LinearLayout(a);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(8));int size=a.dp(40);
  for(int i=0;i<apps.length();i++){JSONObject app=apps.optJSONObject(i);if(app==null)continue;String id=app.optString("id"),title=app.optString("title",id);
   CheckBox box=new CheckBox(a);box.setText(title);box.setTextSize(17);box.setCompoundDrawablePadding(a.dp(12));box.setPadding(a.dp(8),a.dp(6),0,a.dp(6));
   String icon=app.optString("icon","");if(!icon.isEmpty())try{byte[] png=android.util.Base64.decode(icon,android.util.Base64.DEFAULT);android.graphics.Bitmap bm=android.graphics.BitmapFactory.decodeByteArray(png,0,png.length);if(bm!=null){android.graphics.drawable.BitmapDrawable d=new android.graphics.drawable.BitmapDrawable(a.getResources(),bm);d.setBounds(0,0,size,size);box.setCompoundDrawablesRelative(d,null,null,null);}}catch(Exception ignored){}
   list.addView(box,new LinearLayout.LayoutParams(-1,-2));ids.add(id);names.add(title);boxes.add(box);}
  ScrollView scroll=new ScrollView(a);scroll.addView(list);
  int maxList=(int)(a.getResources().getDisplayMetrics().heightPixels*0.55f);   // the list scrolls; the buttons below always show
  LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.addView(scroll,new LinearLayout.LayoutParams(-1,maxList));
  LinearLayout bar=new LinearLayout(a);bar.setOrientation(LinearLayout.HORIZONTAL);bar.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(14));
  Button cancel=new Button(a);cancel.setText("Cancelar");Button review=new Button(a);review.setText("Revisar remoção");
  LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,-2,1f);half.setMarginEnd(a.dp(8));bar.addView(cancel,half);bar.addView(review,new LinearLayout.LayoutParams(0,-2,1f));root.addView(bar);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Aplicativos removíveis ("+ids.size()+")").setView(root).create();
  cancel.setOnClickListener(v->dialog.dismiss());
  review.setOnClickListener(v->{java.util.ArrayList<String> selected=new java.util.ArrayList<>();StringBuilder summary=new StringBuilder();for(int i=0;i<boxes.size();i++)if(boxes.get(i).isChecked()){selected.add(ids.get(i));summary.append(names.get(i)).append('\n');}if(selected.isEmpty()){Toast.makeText(a,"Marque pelo menos um aplicativo.",Toast.LENGTH_SHORT).show();return;}dialog.dismiss();new AlertDialog.Builder(a).setTitle("Confirmar desinstalação").setMessage(summary+"\nOs dados desses aplicativos poderão ser apagados. Aplicativos protegidos não estão nesta lista. Desativação permanente ainda não está disponível.").setPositiveButton("Desinstalar",(x,y)->remove(a,host,selected)).setNegativeButton("Cancelar",null).show();});
  dialog.show();}
 static void remove(Main a,String host,java.util.List<String> ids){a.busy=true;new Thread(()->{Session s=null;try{s=connect(a,host,LgSetup.read(a,"root:"+host));for(String id:ids){JSONObject r=new JSONObject(exec(s,"luna-send -n 1 luna://com.webos.appInstallService/remove '{\"id\":\""+id+"\"}'"));if(!r.optBoolean("returnValue"))throw new IOException("A TV recusou remover "+id);boolean present=true;for(int n=0;n<10;n++){Thread.sleep(500);JSONArray apps=new JSONObject(exec(s,"luna-send -n 1 luna://com.webos.applicationManager/listApps '{}'" )).getJSONArray("apps");present=false;for(int i=0;i<apps.length();i++)if(id.equals(apps.getJSONObject(i).optString("id")))present=true;if(!present)break;}if(present)throw new IOException("Remoção ainda não confirmada: "+id);}a.say("Remoção confirmada pela TV.");try{fetchApps(a,host);}catch(Exception ignored){appsFile(a,host).delete();}}catch(Exception e){a.say(e.getMessage());}finally{if(s!=null)s.disconnect();a.busy=false;}}).start();}
}
